/* Side panel open — 393×852 composition
   The panel itself is 330 wide and sits over the conversation with a 40% scrim. */
.side-panel {
  width: 330px;
  height: 852px;
  padding-top: 52px;
  border-radius: 40px;
  background: var(--bg-canvas);
  box-shadow: 0 4px 20px 0 rgba(113, 117, 142, 0.25);
}

.side-panel__scrim {
  position: absolute;
  inset: 0;
  background: var(--bg-scrim); /* rgba(0, 0, 0, 0.4) */
}

.recents__item {
  display: flex;
  align-items: center;
  gap: 16px;
  min-height: 40px;
  padding: 8px;
  border-radius: 16px;
}

.recents__title {
  font: 400 15px/22px var(--font-ui);
  color: var(--text-primary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.recents__meta {
  display: flex;
  align-items: center;
  gap: 8px;
  font: 400 14px/20px var(--font-ui);
  color: var(--text-secondary);
}

