// Open that file for the full component. The shape of a row:

function RecentRow({ row }) {
  return (
    <div className="recents__item">
      <div className="min-w-0 flex-1">
        <p className="recents__title">{row.title}</p>
        <div className="recents__meta">
          <span>{row.when}</span>
          {row.memories > 0 && (
            <>
              <span aria-hidden>•</span>
              <span>{row.memories} memor{row.memories === 1 ? 'y' : 'ies'} saved</span>
            </>
          )}
        </div>
      </div>
      <button className="size-11 rounded-full" aria-label={`More options for ${row.title}`}>
        <MoreIcon />
      </button>
    </div>
  );
}

